                      const css = getComputedStyle(p)
                      values.push({
                        className: p.className,
                        opacity: css.opacity,
                        filter: css.filter,
                      })
                    }
                    return values
                  }),
                })
                const effectivePixels = pngCanonicalContrastPixels(
                  png,
