        for (const callbacks of listeners.values()) callbacks.delete(fn)
      },
    }
  const graph = {
    container,
    view,
    gridSize: 10,
    isGridEnabled: () => true,
    setCellStyles: forbidden,
    refresh: forbidden,
    getModel: forbidden,
    load: forbidden,
    import: forbidden,
    export: forbidden,
    identity,
    undo,
    selection,
  }
  Object.defineProperty(graph, 'background', { get: () => '#213752', set: forbidden })
  const prototype = { init: vi.fn() },
    ui = {
      editor: {
        graph,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        load: forbidden,
        import: forbidden,
        export: forbidden,
      },
