    )
    expect(forbidden).not.toHaveBeenCalled()
  }
  return {
    send,
    paint,
    replies,
    post,
    raf,
    dispose,
    container,
    paper,
    node,
    graph,
    view,
    listeners,
    assertSemantic,
    ui,
  }
}
